package com.ngtintoreria.erp.pricing;
import jakarta.persistence.*; import java.math.BigDecimal; import java.util.UUID;
@Entity @Table(name="price_rules")
public class PriceRule {
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false) private UUID priceListId; private UUID fabricId; private UUID colorId; private UUID processId; private UUID finishId; @Column(length=20) private String unit="kg"; @Column(precision=14,scale=3) private BigDecimal minQty; @Column(precision=14,scale=3) private BigDecimal maxQty; @Column(nullable=false,precision=14,scale=4) private BigDecimal unitPrice; @Column(precision=8,scale=3) private BigDecimal surchargePct=BigDecimal.ZERO; @Column(precision=8,scale=3) private BigDecimal discountPct=BigDecimal.ZERO; @Column(nullable=false) private boolean active=true;
 public UUID getId(){return id;} public UUID getPriceListId(){return priceListId;} public void setPriceListId(UUID v){priceListId=v;} public UUID getFabricId(){return fabricId;} public void setFabricId(UUID v){fabricId=v;} public UUID getColorId(){return colorId;} public void setColorId(UUID v){colorId=v;} public UUID getProcessId(){return processId;} public void setProcessId(UUID v){processId=v;} public UUID getFinishId(){return finishId;} public void setFinishId(UUID v){finishId=v;} public String getUnit(){return unit;} public void setUnit(String v){unit=v;} public BigDecimal getMinQty(){return minQty;} public void setMinQty(BigDecimal v){minQty=v;} public BigDecimal getMaxQty(){return maxQty;} public void setMaxQty(BigDecimal v){maxQty=v;} public BigDecimal getUnitPrice(){return unitPrice;} public void setUnitPrice(BigDecimal v){unitPrice=v;} public BigDecimal getSurchargePct(){return surchargePct;} public void setSurchargePct(BigDecimal v){surchargePct=v;} public BigDecimal getDiscountPct(){return discountPct;} public void setDiscountPct(BigDecimal v){discountPct=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;}
}
